import 'dart:typed_data';

import 'file_downloader_stub.dart'
    if (dart.library.io) 'file_downloader_native.dart'
    if (dart.library.html) 'file_downloader_web.dart';

/// Saves generated bytes to the user's device.
///
/// On web this creates a Blob URL and clicks a temporary anchor. Other
/// platforms use the stub, which is a no-op until native saving is wired up.
Future<bool> saveFile(
  Uint8List bytes,
  String filename,
  String mimeType,
) =>
    saveFileImpl(bytes, filename, mimeType);
